def gerar(pasta):
    """Grava as amostras em pasta e devolve {tipo: caminho}."""
    os.makedirs(pasta, exist_ok=True)
    caminhos = {}
    for tipo, nome, dados in ARQUIVOS:
        caminho = os.path.join(pasta, nome)
        with open(caminho, "wb") as f:
            f.write(base64.b64decode(dados))
        caminhos[tipo] = caminho
    return caminhos
